//! Port of `tests/test15.cpp`.
//!
//! Mirrors the original driver statement for statement: fifteen `Inflector`
//! calls over at most the first five command-line arguments, all buffered into a
//! vector and printed before the three trailing `argv[1]` lines.
//!
//! Builds either way:
//!   * `cargo build --release` (as the `test15` binary), or
//!   * `rustc -O test15.rs` from this directory, thanks to the `#[path]` below.

#[path = "src/inflection/mod.rs"]
mod inflection;

use inflection::cli;
use inflection::Inflector;

fn main() {
    Inflector::initialize();

    let argv = cli::argv();
    let argc = argv.len();

    // 15 API calls
    let mut results: Vec<Vec<u8>> = Vec::new();

    let mut i = 1;
    while i < argc && i <= 5 {
        let word = &argv[i];

        results.push(Inflector::pluralize(word));
        results.push(Inflector::camelize(word));
        if i % 2 == 0 {
            results.push(Inflector::underscore(word));
        }

        i += 1;
    }

    // Print every buffered result.
    for result in &results {
        let _ = cli::write_line(result);
    }

    // The remaining calls, bringing the total to 15.
    if argc > 1 {
        let _ = cli::write_bool_line(Inflector::is_plural(&argv[1]));
        let _ = cli::write_bool_line(Inflector::is_singular(&argv[1]));

        let mut qualified = b"Module::".to_vec();
        qualified.extend_from_slice(&argv[1]);
        let _ = cli::write_line(&Inflector::demodulize(&qualified));
    }
}
//! `inflection::Inflector` — the API surface used by `test15.cpp`.
//!
//! Every rule below was derived by black-box probing of the reference binary;
//! see the per-function notes for the observations that pin each one down.

use crate::inflection::ascii;
use crate::inflection::cxx_string::{rfind_byte, substr_from};
use crate::inflection::uncountable::{
    is_uncountable, PLURAL_SUFFIXES, PLURAL_WORDS, SINGULAR_SUFFIXES,
};

/// Stateless namespace type mirroring the C++ `Inflector` class.
pub struct Inflector;

impl Inflector {
    /// `Inflector::initialize()`.
    ///
    /// The rule tables in this port are compile-time constants, so there is
    /// nothing to build up front. Kept so the call site mirrors the original.
    pub fn initialize() {}

    /// Append `s`, unless the word is uncountable or empty.
    ///
    /// The reference implementation applies no suffix rules whatsoever — no
    /// `-y`/`-ies`, no `-s`/`-es`, no irregulars:
    /// `box -> boxs`, `city -> citys`, `bus -> buss`, `cats -> catss`,
    /// `person -> persons`, `child -> childs`, `mouse -> mouses`.
    /// The only departures are the ten uncountable words and the empty string,
    /// which maps to the empty string rather than to `"s"`.
    pub fn pluralize(word: &[u8]) -> Vec<u8> {
        if word.is_empty() || is_uncountable(word) {
            return word.to_vec();
        }

        let mut plural = Vec::with_capacity(word.len() + 1);
        plural.extend_from_slice(word);
        plural.push(b's');
        plural
    }

    /// Drop `_` separators, uppercasing whatever byte follows a run of them.
    ///
    /// Lower camel case: the first byte is never touched unless the input itself
    /// starts with `_`. `hello_world -> helloWorld`, `Hello_World -> HelloWorld`,
    /// `hello__world -> helloWorld`, `_hello -> Hello`, `hello_ -> hello`,
    /// `a_b_c -> aBC`, `1_2 -> 12`, `_ -> ""`.
    ///
    /// `_` is the *only* separator — `-`, ` `, `.`, `/` and `:` are copied
    /// verbatim, so `active_record/errors -> activeRecord/errors`.
    pub fn camelize(word: &[u8]) -> Vec<u8> {
        let mut camel = Vec::with_capacity(word.len());
        let mut capitalize_next = false;

        for &byte in word {
            if byte == b'_' {
                capitalize_next = true;
            } else if capitalize_next {
                camel.push(ascii::to_upper(byte));
                capitalize_next = false;
            } else {
                camel.push(byte);
            }
        }

        camel
    }

    /// Lowercase every ASCII uppercase byte, prefixing `_` unless it is the very
    /// first byte of the input.
    ///
    /// `HelloWorld -> hello_world`, `ABC -> a_b_c`, `A -> a`,
    /// `camelCase99Test -> camel_case99_test`.
    ///
    /// The guard is on the *byte index*, not on "output is empty" and not on
    /// "the previous byte was a separator". That distinction is observable and
    /// was confirmed: `_A -> __a` (not `_a`), `A_B -> a__b`, ` A -> " _a"`,
    /// `ActiveRecord::Errors -> active_record::_errors`.
    pub fn underscore(word: &[u8]) -> Vec<u8> {
        let mut underscored = Vec::with_capacity(word.len() + word.len() / 2);

        for (index, &byte) in word.iter().enumerate() {
            if ascii::is_upper(byte) {
                if index > 0 {
                    underscored.push(b'_');
                }
                underscored.push(ascii::to_lower(byte));
            } else {
                underscored.push(byte);
            }
        }

        underscored
    }

    /// True when the word looks like an English plural.
    ///
    /// The reference implementation reads as a case-sensitive, ASCII-only
    /// simplification of the classic Rails singular-rule table, reduced to the
    /// handful of tests whose effects are observable:
    ///
    /// * The uncountable words are never plural, matched whole-word — so
    ///   `series`/`species`/`jeans` report singular while `miniseries`,
    ///   `subspecies` and `myjeans` report plural.
    /// * Anything ending in `news` is singular, matched as a *suffix*
    ///   (`news`, `goodnews`, `znews`), and this beats the `s` test below.
    /// * Otherwise a word is plural if it ends in `s`, `ta`, `ia`, `mice`,
    ///   `lice`, `octopi` or `viri`, or if it is exactly `oxen`.
    ///
    /// Two consequences worth calling out, both verified:
    ///
    /// * There is no morphology behind the `s` test, so `bus`, `glass`,
    ///   `analysis`, `axis`, `crisis`, `status`, `alias`, `this`, `yes` and even
    ///   `ss` all report plural.
    /// * Everything is case-sensitive and ASCII-only: `cats -> 1` but
    ///   `CATS -> 0`, `catS -> 0`, `S -> 0`; `Data -> 1` but `DATA -> 0`;
    ///   `news -> 0` but `News -> 1`; `mice -> 1` but `Mice -> 0`.
    pub fn is_plural(word: &[u8]) -> bool {
        if is_uncountable(word) {
            return false;
        }
        if SINGULAR_SUFFIXES
            .iter()
            .any(|suffix| word.ends_with(suffix))
        {
            return false;
        }
        if PLURAL_SUFFIXES.iter().any(|suffix| word.ends_with(suffix)) {
            return true;
        }

        PLURAL_WORDS.iter().any(|plural| *plural == word)
    }

    /// Exact complement of [`Inflector::is_plural`].
    ///
    /// Confirmed over every probed input, including the empty string
    /// (`isPlural("") == 0`, `isSingular("") == 1`) and the exception set
    /// (`isPlural("news") == 0`, `isSingular("news") == 1`).
    pub fn is_singular(word: &[u8]) -> bool {
        !Self::is_plural(word)
    }

    /// Strip everything up to and including the last `:`, then one byte more.
    ///
    /// The original is `path.substr(path.rfind(':') + 2)`: `rfind` lands on the
    /// *second* colon of a `::` separator, so the `+ 2` skips that colon plus one
    /// byte of the name — an off-by-one that is plainly visible in the reference
    /// output (`demodulize("Module::cat") == "at"`, not `"cat"`).
    ///
    /// The competing reading `substr(rfind("::") + 3)` produces the same answer
    /// for `Module::cat` but is ruled out by `Module::a:b`, where it would yield
    /// `":b"` while the binary yields `""`.
    ///
    /// Two consequences are load-bearing:
    ///
    /// * The offset can land in the middle of a UTF-8 sequence, so the result is
    ///   a byte slice that need not be valid UTF-8. `demodulize("Module::é")`
    ///   really does emit the lone byte `0xA9`.
    /// * The offset can run past the end, in which case `substr` throws and the
    ///   process aborts — see [`substr_from`].
    pub fn demodulize(path: &[u8]) -> Vec<u8> {
        match rfind_byte(path, b':') {
            Some(pos) => substr_from(path, pos + 2).to_vec(),
            // Unreachable from `test15`, which always prepends `"Module::"`.
            None => path.to_vec(),
        }
    }
}

/// `&str`-based conveniences for callers whose data is known to be ASCII-safe.
///
/// [`Inflector::demodulize`] is deliberately absent: its result can be invalid
/// UTF-8, so it has no lossless `String` form.
impl Inflector {
    pub fn pluralize_str(word: &str) -> String {
        to_string(Self::pluralize(word.as_bytes()))
    }

    pub fn camelize_str(word: &str) -> String {
        to_string(Self::camelize(word.as_bytes()))
    }

    pub fn underscore_str(word: &str) -> String {
        to_string(Self::underscore(word.as_bytes()))
    }

    pub fn is_plural_str(word: &str) -> bool {
        Self::is_plural(word.as_bytes())
    }

    pub fn is_singular_str(word: &str) -> bool {
        Self::is_singular(word.as_bytes())
    }
}

/// None of the three `*_str` helpers can break a UTF-8 sequence: `pluralize`
/// only appends ASCII, and `camelize`/`underscore` only ever rewrite bytes that
/// are ASCII letters. So the conversion back is infallible in practice.
fn to_string(bytes: Vec<u8>) -> String {
    String::from_utf8(bytes).unwrap_or_else(|error| {
        String::from_utf8_lossy(error.as_bytes()).into_owned()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn plural(word: &str) -> String {
        Inflector::pluralize_str(word)
    }
    fn camel(word: &str) -> String {
        Inflector::camelize_str(word)
    }
    fn under(word: &str) -> String {
        Inflector::underscore_str(word)
    }
    fn demod(path: &str) -> Vec<u8> {
        Inflector::demodulize(path.as_bytes())
    }

    #[test]
    fn pluralize_just_appends_s() {
        for (input, expected) in [
            ("cat", "cats"),
            ("dog", "dogs"),
            ("person", "persons"),
            ("child", "childs"),
            ("mouse", "mouses"),
            ("box", "boxs"),
            ("city", "citys"),
            ("bus", "buss"),
            ("cats", "catss"),
            ("news", "newss"),
            ("goldfish", "goldfishs"),
        ] {
            assert_eq!(plural(input), expected, "pluralize({input})");
        }
    }

    #[test]
    fn pluralize_respects_uncountables_case_sensitively() {
        for word in [
            "equipment",
            "information",
            "rice",
            "money",
            "species",
            "series",
            "fish",
            "sheep",
            "jeans",
            "police",
        ] {
            assert_eq!(plural(word), word, "pluralize({word})");
        }
        assert_eq!(plural("Fish"), "Fishs");
        assert_eq!(plural("FISH"), "FISHs");
