            ("men", false),
            ("children", false),
            // Case sensitivity.
            ("News", true),
            ("NEWS", false),
            ("CATS", false),
            ("catS", false),
            ("S", false),
            ("Data", true),
            ("DATA", false),
            ("Mice", false),
            ("Oxen", false),
            ("Jeans", true),
            ("", false),
        ] {
