                "isSingular({word})"
            );
        }
    }

    #[test]
    fn demodulize_skips_one_byte_too_many() {
        assert_eq!(demod("Module::cat"), b"at");
        assert_eq!(demod("Module::person"), b"erson");
        assert_eq!(demod("Module::ab"), b"b");
        assert_eq!(demod("Module::a"), b"");
        // rfind(':') lands on the *last* colon anywhere in the string.
        assert_eq!(demod("Module::a:b"), b"");
        assert_eq!(demod("Module::A::B"), b"");
        assert_eq!(demod("Module::::a"), b"");
