//! The uncountable-word table consulted by `Inflector::pluralize`.
//!
//! Determined by black-box probing of the reference binary: of several hundred
//! candidate mass nouns only these ten are returned unchanged by `pluralize`,
//! and the lookup is an exact, case-sensitive, whole-string comparison
//! (`fish` -> `fish` but `Fish` -> `Fishs`, `goldfish` -> `goldfishs`).
//!
//! This is exactly the classic default uncountable list.

/// Words `pluralize` leaves untouched.
pub const UNCOUNTABLE: [&[u8]; 10] = [
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

/// Exact, case-sensitive, whole-string membership test.
pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLE.iter().any(|entry| *entry == word)
}

/// Suffixes that make a word count as already-plural.
///
/// Found by brute force: every 1-3 byte suffix was tested against five
/// different prefixes, and `s`, `ta` and `ia` are the only ones that trigger.
/// `mice`/`lice`/`octopi`/`viri` were then found by testing longer plural forms.
/// All of them are genuine *suffix* tests, not whole-word ones —
/// `slice`, `zoctopi`, `zviri` and `miniseries` all report plural.
pub const PLURAL_SUFFIXES: [&[u8]; 7] = [
    b"s",
    b"ta",
    b"ia",
    b"mice",
    b"lice",
    b"octopi",
    b"viri",
];

/// Suffixes that keep a word singular even though a [`PLURAL_SUFFIXES`] entry
/// also matches.
///
/// `news` ends in `s` yet reports singular, and so does anything else ending in
/// `news` (`goodnews`, `znews`). Note this is *not* the uncountable table:
/// `pluralize("news")` really is `"newss"`.
pub const SINGULAR_SUFFIXES: [&[u8]; 1] = [b"news"];

/// Whole words that count as plural without matching any suffix rule.
///
/// `oxen` alone: `boxen`, `oxenz` and `oxenabc` all report singular, so the
/// match is anchored at both ends.
pub const PLURAL_WORDS: [&[u8]; 1] = [b"oxen"];

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn membership_is_exact_and_case_sensitive() {
        assert!(is_uncountable(b"fish"));
        assert!(is_uncountable(b"police"));
        assert!(!is_uncountable(b"Fish"));
        assert!(!is_uncountable(b"FISH"));
        assert!(!is_uncountable(b"goldfish"));
        assert!(!is_uncountable(b"fishes"));
        assert!(!is_uncountable(b"fish "));
        assert!(!is_uncountable(b""));
        assert!(!is_uncountable(b"news"));
        // Whole-word, so a longer word containing one is not uncountable.
        assert!(!is_uncountable(b"miniseries"));
        assert!(!is_uncountable(b"subspecies"));
        assert!(!is_uncountable(b"myjeans"));
    }
}

//! Process plumbing: raw-byte access to `argv` and a `std::endl`-equivalent
//! line writer.

use std::io::{self, Write};

/// `argv` as raw byte strings, program name included at index 0 — so
/// `argv().len()` is C's `argc` and `argv()[1]` is C's `argv[1]`.
///
/// `std::env::args_os()` is used rather than `std::env::args()` because the
/// latter panics on arguments that are not valid UTF-8, whereas the C++ program
/// happily passes such bytes through `std::string`. For UTF-8 arguments the two
/// are equivalent.
pub fn argv() -> Vec<Vec<u8>> {
    std::env::args_os().map(|arg| os_string_bytes(&arg)).collect()
}

#[cfg(unix)]
fn os_string_bytes(arg: &std::ffi::OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStrExt;
    arg.as_os_str().as_bytes().to_vec()
}

#[cfg(not(unix))]
fn os_string_bytes(arg: &std::ffi::OsString) -> Vec<u8> {
    arg.to_string_lossy().into_owned().into_bytes()
}

/// Write `bytes` followed by `\n`, the equivalent of
/// `std::cout << bytes << std::endl`.
///
/// Raw bytes rather than `println!("{}", …)` because `Inflector::demodulize` can
/// return a fragment of a UTF-8 sequence, which no Rust string type can hold.
/// For valid UTF-8 the emitted bytes are identical to `println!`'s.
///
/// Rust's stdout handle is line-buffered, so the trailing `\n` flushes the line
/// just as `std::endl` does. That matters: the reference program can abort part
/// way through, and everything printed beforehand must already have reached the
/// pipe.
pub fn write_line(bytes: &[u8]) -> io::Result<()> {
    let mut stdout = io::stdout();
    stdout.write_all(bytes)?;
    stdout.write_all(b"\n")
}

/// `std::cout << some_bool << std::endl` — `operator<<` renders `bool` as `1`/`0`
/// unless `std::boolalpha` is set, which the driver never does.
pub fn write_bool_line(value: bool) -> io::Result<()> {
    write_line(if value { b"1" } else { b"0" })
}
//! ASCII-only case mapping.
//!
//! The C++ original calls `std::toupper`/`std::tolower`/`std::isupper` on the
//! individual `char`s of a `std::string`. Nothing in the program ever calls
//! `setlocale`, so those run in the `"C"` locale, where the mapping is the
//! identity for every byte outside `a-z`/`A-Z` — including every byte of a
//! multi-byte UTF-8 sequence.
//!
//! Verified against the reference binary: `underscore("ÉCOLE")` yields the bytes
//! `C3 89 5F 63 5F 6F 5F 6C 5F 65` — the two bytes of `É` are neither uppercased
//! nor treated as an uppercase letter (no `_` is inserted for them), while the
//! following ASCII `C` is.

/// Equivalent of `std::toupper(c)` in the `"C"` locale.
#[inline]
pub fn to_upper(byte: u8) -> u8 {
    if byte.is_ascii_lowercase() {
        byte - (b'a' - b'A')
    } else {
        byte
    }
}

/// Equivalent of `std::tolower(c)` in the `"C"` locale.
#[inline]
pub fn to_lower(byte: u8) -> u8 {
    if byte.is_ascii_uppercase() {
        byte + (b'a' - b'A')
    } else {
        byte
    }
}

/// Equivalent of `std::isupper(c)` in the `"C"` locale.
#[inline]
pub fn is_upper(byte: u8) -> bool {
    byte.is_ascii_uppercase()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii_letters_map() {
        assert_eq!(to_upper(b'a'), b'A');
        assert_eq!(to_lower(b'Z'), b'z');
        assert!(is_upper(b'Q'));
        assert!(!is_upper(b'q'));
    }

    #[test]
    fn everything_else_is_identity() {
        for byte in 0u8..=255 {
            if !byte.is_ascii_alphabetic() {
                assert_eq!(to_upper(byte), byte, "to_upper({byte:#04x})");
                assert_eq!(to_lower(byte), byte, "to_lower({byte:#04x})");
                assert!(!is_upper(byte), "is_upper({byte:#04x})");
            }
        }
    }
}
//! The `inflection` namespace.

// The tree is shared by the library target and, via `#[path]`, by the `test15`
// binary. The binary only needs the byte-level API, so the `&str` conveniences
// and a few helpers read as dead there.
#![allow(dead_code)]

pub mod ascii;
pub mod cli;
pub mod cxx_string;
pub mod inflector;
pub mod uncountable;

pub use inflector::Inflector;
//! Pure-`std` Rust re-implementation of the `inflection` C++ library surface
//! exercised by `tests/test15.cpp`.
//!
//! The C++ original operates on `std::string`, i.e. on raw bytes, with the
//! process running under the default `"C"` locale. Every routine here therefore
//! works on `&[u8]`/`Vec<u8>` rather than `str`/`String`: it is the only way to
//! reproduce the original byte-for-byte, because
//!
//!   * `std::toupper`/`std::tolower` in the `"C"` locale only touch ASCII, so
//!     multi-byte UTF-8 sequences must pass through untouched, and
//!   * `Inflector::demodulize` slices at a byte offset and can therefore split a
//!     UTF-8 sequence, producing output that is not valid UTF-8 at all.
//!
//! Convenience `&str` wrappers are provided for callers that know their input is
//! ASCII-safe.

pub mod inflection;

pub use crate::inflection::inflector::Inflector;
